const menu=document.querySelector('.menu');const nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open);menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');nav.classList.remove('open');menu.textContent='☰'}));
const services={cnh:{title:'Vamos falar da sua CNH.',description:'Explique o que você precisa resolver na sua habilitação para receber a orientação adequada.',items:['Conte a situação atual da sua CNH.','Confirme com a equipe quais serviços estão disponíveis para o seu caso.','Antes da visita, pergunte quais documentos levar.']},debitos:{title:'Entenda as pendências.',description:'Converse com o Rafa sobre os débitos do seu veículo e os próximos passos para regularização.',items:['Informe à equipe qual pendência você deseja entender.','Tenha o documento do veículo disponível no atendimento.','Confirme valores, condições e etapas diretamente com a equipe.']},ajuda:{title:'Vamos encontrar o começo.',description:'Você não precisa saber o nome do serviço. Conte o que aconteceu e o que deseja resolver.',items:['Ligue para (11) 94718-1544.','Explique sua dúvida sobre CNH ou débitos do veículo.','Combine com a equipe o próximo passo do atendimento.']}};const dialog=document.querySelector('dialog');let previousFocus;document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>{const data=services[button.dataset.service];previousFocus=button;document.querySelector('#dialog-title').textContent=data.title;document.querySelector('#dialog-description').textContent=data.description;document.querySelector('#dialog-list').replaceChildren(...data.items.map(text=>{const item=document.createElement('li');item.textContent=text;return item}));dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal()}));document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>previousFocus?.focus());if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.service-card,.process>div,.process li,.location-panel,.contact-panel,.faq>div').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}

const quoteForm=document.querySelector("#quote-form");if(quoteForm){quoteForm.addEventListener("submit",e=>{e.preventDefault();const renavam=document.querySelector("#renavam").value.trim();const placa=document.querySelector("#placa").value.trim().toUpperCase();const message=`Olá, Rafa! Gostaria de consultar o orçamento do meu veículo.\n\nRENAVAM: ${renavam}\nPLACA: ${placa}`;window.open(`https://wa.me/5511947181544?text=${encodeURIComponent(message)}`,"_blank","noopener,noreferrer")})}
